 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The three-color ruler is the consecutive nonzero run at the top edge.
    top = [(c, out[0][c]) for c in range(w) if out[0][c] != 0]
    if len(top) < 3:
        return out
    # These tasks encode the ruler as three adjacent cells.
    start = next((c for c, _ in top if c + 1 < w and out[0][c + 1] != 0 and c + 2 < w and out[0][c + 2] != 0), None)
    if start is None:
        return out
    left_col, left_color = start, out[0][start]
    mid_col, mid_color = start + 1, out[0][start + 1]
    right_col, right_color = start + 2, out[0][start + 2]

    # The middle ruler color is projected vertically through the grid.
    for r in range(h):
        out[r][mid_col] = mid_color

    # A matching left-edge marker turns the left ruler color into an L-shaped ray.
    for r in range(1, h):
        if out[r][0] == left_color:
            for rr in range(r + 1):
                out[rr][left_col] = left_color
            for c in range(left_col + 1):
                out[r][c] = left_color
            # Reassert the middle ruler stripe where the two rays meet.
            out[r][mid_col] = mid_color
            break

    # A matching right-edge marker projects the right ruler color across its row.
    for r in range(1, h):
        if out[r][w - 1] == right_color:
            for c in range(right_col, w):
                out[r][c] = right_color
            break
    return out

